-- The two checklists published on 2026-10-23: Giving a Few Hours Away
-- (Volunteering) and When Good Enough Has to Do (Perfectionism).
-- Generated by `python3 tools/checklists_sql.py --since 2026-10-23`; the repo
-- copy in data/checklists.json is the source. Re-applying is harmless.
insert into public.checklists
  (slug, title, description, category, items, cadence, tags, min_level, published_at)
values
  ('giving-a-few-hours-away', 'Giving a Few Hours Away', 'For wanting to give some time but never getting past the thought. It starts from a skill you already have, turns a cause into one specific shift, counts the real cost in travel and hours, and allows the whole thing to be for you too.', 'Volunteering', '["Start from what you already do — a skill you have beats a cause you only admire.", "Pick a shift, not a cause — two hours on a Saturday is a decision you can keep.", "Ask how long they need you for — a trial month is a fair thing to ask about.", "Check what it will actually cost you — the travel and the hours come out of your week.", "Say what you cannot do up front — being clear now saves resigning later.", "Expect the first session to be awkward — not knowing where the mugs are is normal.", "Let it be for you as well — company and a reason to leave the house both count.", "Stop if it turns into another duty — a volunteer who dreads it helps nobody for long."]'::jsonb, 'weekly', array['Values', 'Loneliness']::text[], 1, '2026-10-23T16:00:00+00:00'::timestamptz),
  ('when-good-enough-has-to-do', 'When Good Enough Has to Do', 'For the piece of work you keep rewriting past the point of improvement. It gets finished written down as a standard, puts a timer on the last pass, and lets you send the version you have rather than the one you are still imagining.', 'Perfectionism', '["Write down what finished actually means — a standard you can name is one you can reach.", "Set a timer for the last pass — polishing has no natural end of its own.", "Ask who else will notice the difference — most of the final tenth is invisible.", "Send the version you have at the deadline — late and perfect is still late.", "Keep a list of what you would change — the ideas survive; the delay does not help them.", "Name the fear under the rewriting — usually it is being judged, not the work itself.", "Let one thing be visibly ordinary this week — proof that nothing falls apart is worth having.", "Count sending it as the achievement — a standard you hit in private helps nobody."]'::jsonb, 'as needed', array['Perfectionism', 'Self-Compassion']::text[], 1, '2026-10-23T16:00:00+00:00'::timestamptz)
on conflict (slug) do update set
  title        = excluded.title,
  description  = excluded.description,
  category     = excluded.category,
  items        = excluded.items,
  cadence      = excluded.cadence,
  tags         = excluded.tags,
  min_level    = excluded.min_level,
  published_at = excluded.published_at;
